insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_text,source_mode,source_refs_text) values ('DOC-CAREER-FIRST-JOB',2,'doc-career-first-job-b2','section','body','Sem experiência não significa sem evidência','Formação, estágios, projetos, monitorias, extensão, pesquisa, voluntariado, apresentações e responsabilidades acadêmicas podem ajudar a demonstrar competências. Descreva o que aconteceu de verdade; não converta exposição em domínio que você ainda não possui.','','static_nontechnical_copy','') on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_text=excluded.payload_text,source_mode=excluded.source_mode,source_refs_text=excluded.source_refs_text;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_text,source_mode,source_refs_text) values ('DOC-CAREER-FIRST-JOB',3,'doc-career-first-job-b3','callout','safety','Antes do exercício profissional','Verifique os requisitos legais e administrativos aplicáveis à sua categoria e à jurisdição onde ocorrerá o exercício. A legislação brasileira exige habilitação legal e inscrição no Conselho Regional competente.','','evidence','SRC-CAREER-COFEN-LEI-7498-1986, SRC-CAREER-COFEN-RES-769-2024') on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_text=excluded.payload_text,source_mode=excluded.source_mode,source_refs_text=excluded.source_refs_text;
