insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_text,source_mode,source_refs_text) values ('DOC-CAREER-CV',2,'doc-career-cv-b2','steps','body','Estrutura mínima útil','','items=Resumo profissional coerente com seu estágio de carreira., Formação e experiências relevantes., Competências sustentadas por exemplos ou evidências., Credenciais e cursos que façam sentido para o alvo., Projetos, pesquisa, extensão ou voluntariado quando acrescentarem informação., Dados de contato apenas no documento final destinado à candidatura, nunca no workspace candidato desta plataforma.','static_nontechnical_copy','') on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_text=excluded.payload_text,source_mode=excluded.source_mode,source_refs_text=excluded.source_refs_text;
