insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_text,source_mode,source_refs_text) values ('DOC-CAREER-RESEARCH',2,'doc-career-research-b2','steps','body','Experimentos de entrada','','items=Participar de grupo ou projeto de pesquisa., Ajudar em revisão de literatura ou organização de dados dentro de um projeto aprovado., Apresentar trabalho ou pôster., Aprender uma ferramenta de análise ou gestão de referências., Conectar uma pergunta prática a uma busca estruturada de evidências.','static_nontechnical_copy','') on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_text=excluded.payload_text,source_mode=excluded.source_mode,source_refs_text=excluded.source_refs_text;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_text,source_mode,source_refs_text) values ('DOC-CAREER-RESEARCH',3,'doc-career-research-b3','section','body','Carreira e pesquisa se alimentam','Projetos podem gerar skills e evidências para o passaporte profissional; gaps de carreira podem gerar perguntas de pesquisa. A integração deve acontecer por referências canônicas entre os domínios, não por cópia de dados.','','static_nontechnical_copy','') on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_text=excluded.payload_text,source_mode=excluded.source_mode,source_refs_text=excluded.source_refs_text;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_text,source_mode,source_refs_text) values ('DOC-CAREER-RESEARCH',4,'doc-career-research-b4','callout','note','Produção científica não é atalho de autoridade','Qualidade de método, transparência e responsabilidade importam mais do que acumular títulos ou publicações desconectadas.','','static_nontechnical_copy','') on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_text=excluded.payload_text,source_mode=excluded.source_mode,source_refs_text=excluded.source_refs_text;
insert into career_editorial_document_candidate(id,editorial_id,slug,template_id,locale,audience,title,lead,source_gate,human_gate,status) values ('DOC-CAREER-INTERNATIONAL','ED-INTERNATIONAL-START','carreira-internacional-primeiros-passos','TPL-ARTICLE-001','pt-BR','PROFESSIONAL','Carreira internacional: comece pela jurisdição, não pelo país dos sonhos','Trabalhar fora depende de regras específicas de reconhecimento, registro, idioma, imigração e empregador. Antes de gastar com cursos ou intermediários, organize a investigação por jurisdição.','PASS','HOLD','DRAFT_CANDIDATE') on conflict(id) do update set title=excluded.title,lead=excluded.lead,source_gate=excluded.source_gate,human_gate=excluded.human_gate,status=excluded.status,updated_at=current_date;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_text,source_mode,source_refs_text) values ('DOC-CAREER-INTERNATIONAL',1,'doc-career-international-b1','steps','body','Monte uma ficha por jurisdição','','items=Autoridade responsável pelo registro profissional., Regras de reconhecimento ou equivalência da formação., Exigências de idioma e como são comprovadas., Autorização migratória ou de trabalho., Documentos e traduções exigidos., Custos, prazos e validade das etapas., Fonte oficial e data da última verificação.','static_nontechnical_copy','') on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_text=excluded.payload_text,source_mode=excluded.source_mode,source_refs_text=excluded.source_refs_text;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_text,source_mode,source_refs_text) values ('DOC-CAREER-INTERNATIONAL',2,'doc-career-international-b2','section','body','Não copie requisitos de outro país','Mesmo países com sistemas de saúde semelhantes podem exigir processos diferentes. Requisitos mudam com o tempo; por isso o banco de Carreira Internacional mantém cada regra ligada à jurisdição, fonte e validade.','','static_nontechnical_copy','') on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_text=excluded.payload_text,source_mode=excluded.source_mode,source_refs_text=excluded.source_refs_text;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_text,source_mode,source_refs_text) values ('DOC-CAREER-INTERNATIONAL',3,'doc-career-international-b3','section','body','Prepare o que é transferível','Idioma, documentação organizada, portfólio de competências, experiência bem descrita e hábitos de verificação ajudam em várias rotas, mesmo quando as exigências regulatórias são diferentes.','','static_nontechnical_copy','') on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_text=excluded.payload_text,source_mode=excluded.source_mode,source_refs_text=excluded.source_refs_text;
