insert into career_editorial_document_candidate(id,editorial_id,slug,template_id,locale,audience,title,lead,source_gate,human_gate,status) values ('DOC-YOUTH-FIRST-STEPS','ED-YOUTH-FIRST-STEPS','primeiros-passos-jovens','TPL-POCKET-GUIDE-001','pt-BR','YOUTH','Quero conhecer Enfermagem: por onde começar?','Você pode explorar a profissão antes de escolher curso, instituição ou área. O objetivo da primeira fase é construir perguntas melhores.','PASS','HOLD','DRAFT_CANDIDATE') on conflict(id) do update set title=excluded.title,lead=excluded.lead,source_gate=excluded.source_gate,human_gate=excluded.human_gate,status=excluded.status,updated_at=current_date;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_text,source_mode,source_refs_text) values ('DOC-YOUTH-FIRST-STEPS',1,'doc-youth-first-steps-b1','steps','core_sections','Uma sequência simples','','items=Entenda as diferentes habilitações e caminhos formativos., Explore alguns contextos de atuação., Converse com profissionais sobre rotina e aprendizagem, não apenas salário., Compare como você gosta de aprender e trabalhar., Pesquise cursos apenas depois de entender o caminho que está avaliando., Registre dúvidas e volte a elas depois de novas experiências.','static_nontechnical_copy','') on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_text=excluded.payload_text,source_mode=excluded.source_mode,source_refs_text=excluded.source_refs_text;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_text,source_mode,source_refs_text) values ('DOC-YOUTH-FIRST-STEPS',2,'doc-youth-first-steps-b2','section','body','Faça perguntas concretas','Como é um dia comum? O que costuma ser difícil no começo? Que habilidades fazem diferença? O que você gostaria de ter sabido antes de escolher? Perguntas assim produzem informação melhor do que ''você gosta da profissão?''.','','static_nontechnical_copy','') on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_text=excluded.payload_text,source_mode=excluded.source_mode,source_refs_text=excluded.source_refs_text;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_text,source_mode,source_refs_text) values ('DOC-YOUTH-FIRST-STEPS',3,'doc-youth-first-steps-b3','reflection','body','Seu próximo passo não precisa ser grande','Ler uma fonte oficial, assistir a uma atividade educativa, participar de uma feira de profissões ou conversar com alguém da área já pode mudar a qualidade da sua decisão.','','static_nontechnical_copy','') on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_text=excluded.payload_text,source_mode=excluded.source_mode,source_refs_text=excluded.source_refs_text;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_text,source_mode,source_refs_text) values ('DOC-YOUTH-FIRST-STEPS',4,'doc-youth-first-steps-b4','callout','note','Escolha é processo','Você pode mudar de ideia. Explorar com método não significa indecisão; significa reduzir decisões baseadas apenas em imagem ou expectativa.','','static_nontechnical_copy','') on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_text=excluded.payload_text,source_mode=excluded.source_mode,source_refs_text=excluded.source_refs_text;
insert into career_editorial_document_candidate(id,editorial_id,slug,template_id,locale,audience,title,lead,source_gate,human_gate,status) values ('DOC-YOUTH-TECH-GRAD','ED-YOUTH-TECH-GRAD','tecnico-ou-graduacao-enfermagem','TPL-ARTICLE-001','pt-BR','YOUTH','Técnico de Enfermagem ou graduação em Enfermagem: caminhos diferentes','Os dois caminhos pertencem ao campo da Enfermagem, mas correspondem a formações e habilitações profissionais diferentes. A comparação precisa respeitar essas diferenças.','HOLD','HOLD','HOLD_HUMAN') on conflict(id) do update set title=excluded.title,lead=excluded.lead,source_gate=excluded.source_gate,human_gate=excluded.human_gate,status=excluded.status,updated_at=current_date;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_text,source_mode,source_refs_text) values ('DOC-YOUTH-TECH-GRAD',1,'doc-youth-tech-grad-b1','comparison','body','O que não fazer','Não trate o curso técnico como ''faculdade curta'' nem a graduação como simples continuação automática do técnico. A legislação profissional distingue categorias e atribuições, e os sistemas educacionais organizam cada formação em marcos próprios.','','evidence','SRC-CAREER-COFEN-LEI-7498-1986, SRC-CAREER-COFEN-DEC-94406-1987, SRC-CAREER-MEC-DCN-ENF-2026, SRC-CAREER-MEC-CNCT-2026') on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_text=excluded.payload_text,source_mode=excluded.source_mode,source_refs_text=excluded.source_refs_text;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_text,source_mode,source_refs_text) values ('DOC-YOUTH-TECH-GRAD',2,'doc-youth-tech-grad-b2','section','body','Como comparar','Olhe para o perfil de formação, responsabilidades profissionais, tempo disponível, contexto financeiro, instituições regulares e o tipo de trajetória que você quer experimentar. Se possível, converse com profissionais das duas formações.','','static_nontechnical_copy','') on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_text=excluded.payload_text,source_mode=excluded.source_mode,source_refs_text=excluded.source_refs_text;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_text,source_mode,source_refs_text) values ('DOC-YOUTH-TECH-GRAD',3,'doc-youth-tech-grad-b3','section','body','Use fontes atuais','As Diretrizes Curriculares da graduação foram atualizadas em 2026. O CNCT também passou por processo de atualização em 2026. Por isso, detalhes de curso devem ser verificados nos sistemas oficiais atuais, não em posts antigos ou tabelas copiadas.','','evidence','SRC-CAREER-MEC-DCN-ENF-2026, SRC-CAREER-MEC-CNCT-2026') on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_text=excluded.payload_text,source_mode=excluded.source_mode,source_refs_text=excluded.source_refs_text;
insert into career_editorial_block_candidate(document_id,block_order,block_id,block_type,semantic_role,heading,body,payload_text,source_mode,source_refs_text) values ('DOC-YOUTH-TECH-GRAD',4,'doc-youth-tech-grad-b4','callout','note','Escolha não define toda a vida profissional','Uma decisão formativa organiza o próximo caminho, mas trajetórias podem evoluir com novas formações, experiências e objetivos.','','static_nontechnical_copy','') on conflict(document_id,block_id) do update set block_order=excluded.block_order,block_type=excluded.block_type,semantic_role=excluded.semantic_role,heading=excluded.heading,body=excluded.body,payload_text=excluded.payload_text,source_mode=excluded.source_mode,source_refs_text=excluded.source_refs_text;
